<template><div class="space-y-7"><AppPageHeader eyebrow="Financeiro" title="Reconciliação financeira" description="Trate somente as exceções que exigem decisão humana, mantendo o histórico financeiro e acadêmico protegido."/><div v-if="error" class="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ error }}</div><section class="grid grid-cols-2 gap-3 lg:grid-cols-3 xl:grid-cols-6"><Metric label="Em aberto" :value="summary.open_reviews" icon="pulse"/><Metric label="Em análise" :value="summary.in_review" icon="users"/><Metric label="Aprovados" :value="summary.approved_payments" icon="shield"/><Metric label="Reembolsados" :value="summary.refunded_payments" icon="card"/><Metric label="Receita líquida" :value="money(summary.net_total)" icon="chart"/><Metric label="Líquido no mês" :value="money(summary.monthly_net)" icon="chart"/></section>
<section class="premium-card overflow-hidden"><div class="flex flex-col gap-3 border-b border-slate-100 px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><p class="premium-kicker">Exceções</p><h2 class="mt-1 font-bold text-slate-900">Fila de revisão</h2></div><select v-model="filter" @change="loadReviews" class="min-w-44"><option value="">Todas as situações</option><option>OPEN</option><option>IN_REVIEW</option><option>RESOLVED</option><option>DISMISSED</option></select></div><div v-if="loading" class="p-8 text-sm text-slate-400">Carregando…</div><div v-else-if="!reviews.length" class="m-5 rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center text-sm text-slate-400">Nenhuma revisão financeira neste filtro.</div><div v-else class="divide-y divide-slate-100"><article v-for="review in reviews" :key="review.id" class="p-5 sm:p-6"><div class="flex flex-col gap-4 lg:flex-row lg:items-start"><div class="flex-1"><div class="flex flex-wrap items-center gap-2"><span class="flex h-9 w-9 items-center justify-center rounded-xl bg-amber-50 text-amber-700"><NavIcon name="chart"/></span><div><p class="font-bold text-slate-900">{{ review.reason }}</p><p class="mt-0.5 text-xs text-slate-400">{{ review.provider }} · {{ money(review.payment_amount) }}</p></div><span class="rounded-full bg-slate-100 px-2.5 py-1 text-[10px] font-bold text-slate-600">{{ review.status }}</span><span class="rounded-full bg-amber-50 px-2.5 py-1 text-[10px] font-bold text-amber-700">{{ review.priority }}</span></div><p class="mt-3 break-all text-xs text-slate-400">Pagamento {{ review.payment_id }} · status {{ review.payment_status }}</p></div><button v-if="review.status==='OPEN'" @click="claim(review)" class="rounded-xl border border-slate-200 bg-white px-3.5 py-2 text-xs font-bold text-slate-600 shadow-sm hover:bg-slate-50">Assumir caso</button></div><div v-if="['OPEN','IN_REVIEW'].includes(review.status)" class="mt-5 grid gap-2 rounded-2xl bg-slate-50 p-3 md:grid-cols-[210px_1fr_auto]"><select v-model="drafts[review.id].action"><option>KEEP_ACCESS</option><option>REVOKE_ACCESS</option><option>MARK_APPROVED</option><option>MARK_REFUNDED</option><option>DISMISS</option></select><input v-model="drafts[review.id].notes" placeholder="Registre a justificativa da decisão"/><button :disabled="drafts[review.id].notes.length<3" @click="resolve(review)" class="rounded-xl px-4 py-2 text-xs font-bold text-white disabled:opacity-40" :style="{background:'var(--brand-primary)'}">Resolver caso</button></div></article></div></section></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import Metric from'../components/OperationsMetric.vue';import NavIcon from'../components/NavIcon.vue';import AppPageHeader from'../components/AppPageHeader.vue';import{claimFinancialReview,getFinancialSummary,listFinancialReviews,resolveFinancialReview}from'../api/financial';const summary=ref({}),reviews=ref([]),loading=ref(true),error=ref(''),filter=ref(''),drafts=reactive({});const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});function initDrafts(){for(const r of reviews.value)if(!drafts[r.id])drafts[r.id]={action:'KEEP_ACCESS',notes:''}}async function loadSummary(){summary.value=(await getFinancialSummary()).data}async function loadReviews(){loading.value=true;try{reviews.value=(await listFinancialReviews(filter.value?{status_filter:filter.value}:{})).data;initDrafts()}catch(e){error.value=e.response?.data?.detail||'Erro ao carregar revisões.'}finally{loading.value=false}}async function claim(r){try{Object.assign(r,(await claimFinancialReview(r.id)).data)}catch(e){error.value=e.response?.data?.detail||'Não foi possível assumir o caso.'}}async function resolve(r){try{Object.assign(r,(await resolveFinancialReview(r.id,drafts[r.id])).data);await loadSummary()}catch(e){error.value=e.response?.data?.detail||'Não foi possível resolver o caso.'}}onMounted(async()=>{try{await Promise.all([loadSummary(),loadReviews()])}catch(e){error.value=e.response?.data?.detail||'Erro ao carregar financeiro.'}})</script>
